const items=window.DISCOVERIES;
const cats=['games','consoles','celulares','ia','gadgets','curiosidades'];
const colors={games:'#b39aff',consoles:'#ff939b',celulares:'#ffd0ad',ia:'#a6adff',gadgets:'#8ee8d6',curiosidades:'#acc8ff'};
const paths={all:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',games:'M7 7h10c3 0 5 5 5 9s-3 5-6 1H8c-3 4-6 3-6-1s2-9 5-9z M6 10v5 M3.5 12.5h5 M16 11h.1 M19 14h.1',celulares:'M7 2h10a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z M10 5h4 M11 19h2',ia:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z M19 2v4 M17 4h4',gadgets:'M3 14v-3a9 9 0 0 1 18 0v3 M3 12h4v9H5a2 2 0 0 1-2-2z M21 12h-4v9h2a2 2 0 0 0 2-2z',curiosidades:'M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0z M6 8C-4 15 1 25 17 15S29 0 18 7',save:'M6 3h12v19l-6-4-6 4z',shuffle:'M3 6h3c4 0 8 12 12 12h3 M18 15l3 3-3 3 M3 18h3c1 0 3-2 4-4 M14 10c2-3 3-4 4-4h3 M18 3l3 3-3 3',arrow:'M5 12h14 M13 6l6 6-6 6',trophy:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v6 M7 21h10'};
paths.consoles=paths.games;
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.ia}"/></svg>`;
let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'pt',filter='all',qIndex=0,answer=null,result=false,current=null;
const L=(pt,en)=>lang==='pt'?pt:en;
const C=()=>({all:L('Tudo junto','Everything'),games:'Games',consoles:'Consoles',celulares:L('Celulares','Phones'),ia:L('Inteligência artificial','Artificial intelligence'),gadgets:'Gadgets',curiosidades:L('Curiosidades','Curiosities')});
const title=x=>x[lang==='pt'?'titlePT':'titleEN'],summary=x=>x[lang==='pt'?'summaryPT':'summaryEN'],fact=x=>x[lang==='pt'?'fact':'factEN'];
const date=x=>new Intl.DateTimeFormat(lang==='pt'?'pt-BR':'en-US',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(x.published+'T12:00:00Z'));
const key='anderzilla-playtest-v2',fresh=()=>({saved:[],opened:[],interests:[],quizDone:false});
let state=fresh(),storage=true;
try{const old=JSON.parse(localStorage.getItem(key)||'null');if(old&&typeof old==='object'){for(const field of ['saved','opened'])state[field]=Array.isArray(old[field])?[...new Set(old[field].filter(id=>items.some(x=>x.id===id)))]:[];state.interests=Array.isArray(old.interests)?old.interests.filter(x=>cats.includes(x)):[];state.quizDone=old.quizDone===true;}}catch{storage=false;}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{storage=false;}}
let timer;function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),3200);}
const seen=()=>new Set(items.filter(x=>state.opened.includes(x.id)).map(x=>x.category));
const saveLabel=id=>state.saved.includes(id)?L('Tirar da mochila','Remove from backpack'):L('Guardar na mochila','Save to backpack');
function art(x,extra=''){const native={celulares:'<div class="phone"></div>',ia:'<div class="orb"></div>',curiosidades:'<div class="planet"></div>'};return `<div class="art ${x.category} ${extra}" aria-hidden="true">${native[x.category]||icon(x.category)}</div>`;}
function card(x){return `<article class="card" style="--cat:${colors[x.category]}">${art(x)}<div class="card-copy"><div class="card-category"><span>${C()[x.category]}</span>${x.published<'2026-01-01'?`<span class="archive">${L('ARQUIVO','ARCHIVE')}</span>`:''}</div><h3><button data-open="${x.id}">${title(x)}</button></h3><p>${summary(x)}</p><div class="card-bottom"><small>${x.sourceName}<br><time datetime="${x.published}">${date(x)}</time></small><button class="save" data-save="${x.id}" aria-label="${saveLabel(x.id)}" aria-pressed="${state.saved.includes(x.id)}">${icon('save')}</button></div></div></article>`;}
const socials=[['YouTube','https://www.youtube.com/@anderzilla-tv'],['Twitch','https://www.twitch.tv/anderzillacwb'],['TikTok','https://www.tiktok.com/@anderzilla'],['Instagram','https://www.instagram.com/anderzilla/'],['Kick','https://kick.com/anderzilla']];
function header(){const route=location.hash.slice(1)||'home';return `<div class="preview"><span>${L('PLAYTEST 02 · PRÉVIA LOCAL','PLAYTEST 02 · LOCAL PREVIEW')}</span><div class="languages" aria-label="Language"><button data-lang="pt" aria-pressed="${lang==='pt'}">PT</button><span>/</span><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></div><header><a class="brand" href="#home"><img src="assets/anderzilla-ghost.png" alt="" width="45" height="45"><div class="wordmark">ANDER<span>ZILLA</span><small>${L('GAMES. TECH. BOAS DESCOBERTAS.','GAMES. TECH. GREAT FINDS.')}</small></div></a><nav aria-label="${L('Principal','Main')}">${[['home','Radar'],['saved',L('Minha mochila','My backpack')],['quiz',L('Desafio','Challenge')],['channels',L('Canais','Channels')]].map(([r,label])=>`<a href="#${r}" ${r===route?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="actions"><a href="#saved" aria-label="${L('Minha mochila','My backpack')}: ${state.saved.length}">${icon('save')} <span class="count">${state.saved.length}</span></a><a class="profile-link" href="#profile"><img src="assets/anderzilla-ghost.png" alt=""><span>${L('Seu radar','Your radar')}</span></a></div></header>`;}
function passport(){const count=seen().size;return `<aside class="passport"><div class="passport-top"><img src="assets/anderzilla-ghost.png" alt="AnderZilla Ghost" width="62" height="62"><div><p class="eyebrow">${L('SEU PASSAPORTE','YOUR PASSPORT')}</p><h2>${L('Curiosidade<br>desbloqueada.','Curiosity<br>unlocked.')}</h2></div></div><p>${L('Abra descobertas de temas diferentes e complete seu mapa. Cada território tem algo pra explorar.','Open discoveries across different topics and complete your map. Every territory has something to explore.')}</p><div class="progress-label"><span>${L('Territórios explorados','Territories explored')}</span><b>${count}/6</b></div><div class="progress" role="progressbar" aria-label="${L('Territórios','Territories')}" aria-valuemin="0" aria-valuemax="6" aria-valuenow="${count}"><div style="--progress:${count/6*100}%"></div></div><div class="stamps">${cats.map(cat=>`<span class="stamp ${seen().has(cat)?'done':''}" title="${C()[cat]}">${icon(cat)}</span>`).join('')}</div><a class="button secondary" href="#profile">${L('Escolher meus interesses','Choose my interests')}</a><small>${storage?L('Progresso só neste navegador. Sem conta.','Progress stays in this browser. No account.'):L('Armazenamento indisponível. Só nesta sessão.','Storage unavailable. This session only.')}</small></aside>`;}
function feed(){return [...items].sort((a,b)=>Number(state.interests.includes(b.category))-Number(state.interests.includes(a.category))||b.published.localeCompare(a.published)).filter(x=>filter==='all'||x.category===filter).map(card).join('');}
function home(){return `<div class="ticker"><strong>${L('NO RADAR','ON THE RADAR')}</strong><span>Mario Kart / Switch 2</span><span>Gemini + Find Hub</span><span>Gears of War</span><span>iPhone 17e</span></div><div class="wrap"><div class="welcome"><div><h1>${L('E aí, player. Bora descobrir?','Hey, player. Ready to explore?')}</h1><p>${L('Games, IA e coisas que fazem a gente dizer: “olha isso!”','Games, AI and things that make us say: “check this out!”')}</p></div><button class="surprise" data-random aria-label="${L('Me surpreenda','Surprise me')}">${icon('shuffle')}${L('Me surpreenda','Surprise me')}</button></div><div class="hero-layout"><section class="hero"><img src="assets/discovery-room.png" width="1536" height="1024" alt=""><p class="eyebrow"><span class="tag">GHOST'S HIDEOUT</span>${L('ABRA UMA NOVA FASE','ENTER A NEW LEVEL')}</p><h2>${L('Seu próximo<br><em>“olha isso!”</em><br>está aqui.','Your next<br><em>“check this out!”</em><br>starts here.')}</h2><p>${L('Uma corrida nova, um gadget improvável ou uma IA que resolve aquele perrengue. Escolha sua próxima descoberta.','A new race, an unexpected gadget or AI that solves a little everyday problem. Pick your next discovery.')}</p><div class="hero-buttons"><button class="button" data-feed>${L('Entrar no radar','Explore the radar')}${icon('arrow')}</button><button class="button secondary" data-random>${icon('shuffle')}${L('Abrir uma surpresa','Open a surprise')}</button></div><span class="art-note">${L('Arte conceitual · não representa produto real','Concept art · not an actual product')}</span></section>${passport()}</div><div class="dock" role="group" aria-label="Radar">${['all',...cats].map(cat=>`<button class="category" style="--cat:${colors[cat]||'#a8bdff'}" data-filter="${cat}" aria-pressed="${filter===cat}">${icon(cat)}${C()[cat]}</button>`).join('')}</div><div class="content" id="feed-start"><section aria-labelledby="feed-title"><div class="heading"><h2 id="feed-title" tabindex="-1">${L('Drops no seu <span>radar</span>','Drops on your <span>radar</span>')}</h2><small>${L('Curadoria inicial · fontes e datas reais','Starter collection · real sources and dates')}</small></div><div class="feed" id="feed" aria-live="polite">${feed()}</div></section><aside class="sidebar"><section class="quiz-teaser">${icon(state.quizDone?'trophy':'ia')}<p class="eyebrow">${L('DESAFIO DA VEZ','YOUR NEXT CHALLENGE')}</p><h2>${state.quizDone?L('Curiosidade em dia.','Curiosity powered up.'):L('Você sabe mesmo<br>como isso funciona?','Do you really know<br>how this works?')}</h2><p>${L('Três perguntas. Umas descobertas inesperadas. Acerte, entenda e desbloqueie seu selo.','Three questions. A few unexpected discoveries. Learn the details and unlock your badge.')}</p><a class="button" href="#quiz">${L('Aceitar desafio','Accept challenge')}${icon('arrow')}</a></section><section class="sidebar-panel"><h2>${L('O papo continua','Keep the conversation going')}</h2>${socials.slice(0,3).map(([name,url])=>`<a class="channel-link" href="${url}" target="_blank" rel="noopener noreferrer"><span>${name[0]}</span>${name}<b>↗</b></a>`).join('')}<p>${L('Canais do Ghost. Status de live e horários só quando confirmados.','Ghost’s channels. Live status and schedules require confirmation.')}</p></section><section class="loot"><h2>${L('Quem guarda, descobre depois.','Good finds deserve a save.')}</h2><p>${L('Sua mochila junta o que vale revisitar. Abra, salve, compare e volte quando quiser.','Your backpack keeps what is worth revisiting. Open, save, compare and come back anytime.')}</p><a href="#saved">${L('Abrir minha mochila →','Open my backpack →')}</a></section></aside></div><section class="return-band"><img src="assets/anderzilla-ghost.png" alt="" width="68" height="68"><div><h2>${L('Um radar com a sua cara.','A radar that feels like you.')}</h2><p>${L('Escolha seus temas. Eles aparecem primeiro na próxima visita.','Choose your topics. They appear first on your next visit.')}</p></div><a class="button secondary" href="#profile">${L('Personalizar meu radar','Personalize my radar')}${icon('arrow')}</a></section></div>`;}
function saved(){const list=items.filter(x=>state.saved.includes(x.id));return `<div class="wrap subpage"><p class="eyebrow">${icon('save')}${L('MINHA MOCHILA','MY BACKPACK')}</p><h1>${L('Coisas boas merecem um save.','Good discoveries deserve a save.')}</h1><p class="lede">${L('Sua coleção pessoal, guardada neste navegador e pronta para revisitar.','Your personal collection, stored in this browser and ready to revisit.')}</p><div class="feed saved-feed">${list.length?list.map(card).join(''):`<div class="empty">${icon('save')}<h2>${L('Sua mochila espera o primeiro loot.','Your backpack awaits its first find.')}</h2><p>${L('Toque no marcador de uma descoberta para guardar aqui. Sem conta e sem pressa.','Tap the bookmark on a discovery to save it here. No account and no rush.')}</p><a class="button" href="#home">${L('Voltar ao radar','Back to radar')}</a></div>`}</div></div>`;}
const questions=[{cat:'gadgets',pt:'Na tradução com AirPods descrita pela Apple, quem faz parte essencial da mágica?',en:'In the AirPods translation described by Apple, what is essential to the magic?',ptOptions:['Só o fone, sem outro dispositivo.','Apple Intelligence no iPhone compatível.','Qualquer rádio Bluetooth.'],enOptions:['Just the earbuds, no other device.','Apple Intelligence on a compatible iPhone.','Any Bluetooth radio.'],correct:1},{cat:'curiosidades',pt:'As auroras de Netuno anunciadas em 2025 foram registradas por qual instrumento?',en:'Which instrument captured the Neptune auroras announced in 2025?',ptOptions:['Uma câmera de celular em órbita.','O telescópio espacial Hubble.','O espectrógrafo de infravermelho próximo do Webb.'],enOptions:['A phone camera in orbit.','The Hubble Space Telescope.','Webb’s near-infrared spectrograph.'],correct:2},{cat:'celulares',pt:'Qual conexão com acessórios a Apple adicionou ao iPhone 17e?',en:'Which accessory connection did Apple add to iPhone 17e?',ptOptions:['MagSafe.','Entrada para cartuchos.','Porta de fita cassete.'],enOptions:['MagSafe.','A cartridge slot.','A cassette tape port.'],correct:0}];
function quiz(){if(result)return `<div class="wrap subpage quiz-page"><div class="badge-large">${icon('trophy')}</div><h1>${L('Selo: curiosidade em dia.','Badge: curiosity powered up.')}</h1><p class="lede">${L('Você completou as três perguntas. O selo fica neste navegador, sem recompensas financeiras ou ranking inventado.','You completed all three questions. Your badge stays in this browser, without financial rewards or a fabricated leaderboard.')}</p><button class="button" data-replay>${L('Jogar de novo','Play again')}</button> <a class="button secondary" href="#home">Radar</a></div>`;const q=questions[qIndex],source=items.find(x=>x.category===q.cat);return `<div class="wrap subpage quiz-page"><p class="eyebrow">${icon('trophy')}${L('DESAFIO DA VEZ','YOUR NEXT CHALLENGE')}</p><h1>${L('Um checkpoint para a curiosidade.','A checkpoint for your curiosity.')}</h1><p class="lede">${L('O desafio usa as fontes do radar. Pode tentar de novo: cada resposta vem com uma explicação.','This challenge uses sources from the radar. Try again anytime: every answer comes with an explanation.')}</p><section class="quiz-box"><p class="quiz-progress">${L('PERGUNTA','QUESTION')} ${qIndex+1} / 3</p><h2>${q[lang]}</h2><div class="answers">${q[lang+'Options'].map((label,i)=>`<button class="answer ${answer===i?(i===q.correct?'correct':'wrong'):''}" data-answer="${i}" ${answer!==null?'disabled':''}>${String.fromCharCode(65+i)}. ${label}</button>`).join('')}</div>${answer===null?'':`<div class="feedback" role="status"><strong>${answer===q.correct?L('Boa! Esse é o detalhe.','Nice! That is the detail.'):L('Quase. Veja o que a fonte explica:','Almost. Here is what the source explains:')}</strong><p>${fact(source)}</p><a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.sourceName} ↗</a></div><button class="button" ${answer===q.correct?'data-next':'data-retry'}>${answer!==q.correct?L('Tentar novamente','Try again'):qIndex===2?L('Ver meu selo','See my badge'):L('Próxima pergunta','Next question')}${icon('arrow')}</button>`}</section></div>`;}
function profile(){return `<div class="wrap subpage"><p class="eyebrow">${L('SEU RADAR','YOUR RADAR')}</p><h1>${L('Escolha seu universo.','Choose your universe.')}</h1><p class="lede">${L('Seus assuntos favoritos aparecem primeiro. Você ainda pode explorar todos os temas.','Your favorite topics appear first. You can still explore every topic.')}</p><div class="interest-list" role="group" aria-label="${L('Interesses','Interests')}">${cats.map(cat=>`<button class="interest" data-interest="${cat}" aria-pressed="${state.interests.includes(cat)}">${icon(cat)} ${C()[cat]}</button>`).join('')}</div><div style="max-width:430px">${passport()}</div><div class="notice">${L('Preferências, mochila e progresso ficam somente neste navegador. Sem login, sincronização entre dispositivos ou coleta no servidor.','Preferences, backpack and progress stay only in this browser. No login, cross-device sync or server-side collection.')}</div><a class="button" href="#home">${L('Voltar ao meu radar','Back to my radar')}</a><button class="quiet" data-reset>${L('Limpar meus dados locais','Clear my local data')}</button></div>`;}
function channels(){return `<div class="wrap subpage"><p class="eyebrow">@ANDERZILLA</p><h1>${L('Aperta o play. Puxa uma cadeira.','Press play. Pull up a chair.')}</h1><p class="lede">${L('Games, tech e conversa com o Ghost. Escolha onde acompanhar.','Games, tech and conversations with Ghost. Choose where to follow.')}</p><div class="channel-grid">${socials.map(([name,url])=>`<section class="channel-card"><img src="assets/anderzilla-ghost.png" alt="AnderZilla Ghost"><h2>${name}</h2><p>${L('Sem indicador de “ao vivo” ou agenda até haver confirmação real.','No “live now” indicator or schedule without confirmation.')}</p><a class="button secondary" href="${url}" target="_blank" rel="noopener noreferrer">${L('Ir para o canal','Visit channel')} ↗</a></section>`).join('')}</div></div>`;}
function sponsor(){return `<div class="wrap subpage"><p class="eyebrow">${L('PARCERIAS','PARTNERSHIPS')}</p><h1>${L('Marcas também podem entrar na conversa.','Brands can join the conversation too.')}</h1><p class="lede">${L('Games, gadgets e IA dão boas histórias quando existe algo interessante para mostrar. Demonstrações entram na pauta com identificação comercial e opinião independente.','Games, gadgets and AI make good stories when there is something interesting to show. Demonstrations join the editorial mix with commercial disclosure and independent opinion.')}</p><div class="notice">${L('Conceito comercial: sem patrocinadores, preços ou formulário simulado. Contato e recebimento serão validados antes de operar.','Commercial concept: no sponsors, prices or simulated form. Contact and receiving process will be validated before operation.')}</div><h2>ForgeKit</h2><p class="lede">${L('Para quem também quer construir: o produto próprio é uma opção contextual. Confira conteúdo, preço e condições na Gumroad.','For people who also want to build: our own product is a contextual option. Check contents, price and terms on Gumroad.')}</p><a class="button secondary" href="https://anderzilla.gumroad.com/l/edkel" target="_blank" rel="noopener noreferrer">ForgeKit / Gumroad ↗</a></div>`;}
function footer(){return `<footer><a class="wordmark" href="#home">ANDER<span>ZILLA</span></a><p>${L('Um esconderijo para quem gosta de games e de fuçar no futuro.','A hideout for people who love games and tinkering with the future.')}</p><a href="#channels">${L('Canais','Channels')}</a><a href="#sponsor">${L('Parcerias','Partnerships')}</a><a href="https://anderzilla.gumroad.com/l/edkel" target="_blank" rel="noopener noreferrer">ForgeKit / ${L('produto próprio','own product')} ↗</a><small>${L('Playtest local com curadoria datada e artes conceituais. Não é feed automático. Mochila, interesses e progresso ficam no navegador; sem pontos com valor financeiro.','Local playtest with dated curation and concept artwork. Not an automatic news feed. Backpack, interests and progress stay in your browser; no points with monetary value.')}</small></footer>`;}
function render(focus=false){document.documentElement.lang=lang==='pt'?'pt-BR':'en';document.title='AnderZilla — Radar';const route=location.hash.slice(1)||'home';document.getElementById('shell').innerHTML=header()+`<main id="main" tabindex="-1">${({home,saved,quiz,profile,channels,sponsor}[route]||home)()}</main>`+footer();if(focus){document.getElementById('main').focus({preventScroll:true});window.scrollTo(0,0);}}
const dialog=document.getElementById('detail');
function openItem(id){const x=items.find(x=>x.id===id);if(!x)return;const newTerritory=!seen().has(x.category);if(!state.opened.includes(id)){state.opened.push(id);persist();}current=x;const pass=document.querySelector('.hero-layout>.passport');if(pass)pass.outerHTML=passport();document.getElementById('dialog-body').innerHTML=art(x,'dialog-art')+`<div class="dialog-copy"><p class="eyebrow">${C()[x.category]}</p><h2 id="dialog-title">${title(x)}</h2><p class="source">${x.sourceName} · <time datetime="${x.published}">${date(x)}</time></p><p>${summary(x)}</p><div class="fact"><strong>${L('O detalhe que vale o clique','The detail worth the click')}</strong><p>${fact(x)}</p></div><div class="dialog-buttons"><a class="button" href="${x.url}" target="_blank" rel="noopener noreferrer">${L('Ver fonte original','Read original source')} ↗</a><button class="button secondary" data-save="${x.id}" aria-pressed="${state.saved.includes(id)}">${icon('save')}<span>${saveLabel(id)}</span></button><button class="quiet" data-random>${L('Outra descoberta →','Another discovery →')}</button></div><p class="note">${L('Resumo de curadoria, não teste próprio nem link de afiliado. A data se refere à publicação original.','Curated summary, not a hands-on review or affiliate link. Date refers to original publication.')}</p></div>`;if(!dialog.open)dialog.showModal();document.body.classList.add('modal-open');if(newTerritory)toast(L('Novo território no seu passaporte!','New territory in your passport!'));}
function random(){let pool=items.filter(x=>!state.opened.includes(x.id));if(!pool.length)pool=items.filter(x=>x.id!==current?.id);openItem(pool[Math.floor(Math.random()*pool.length)].id);}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.lang){lang=b.dataset.lang;const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render();document.querySelector(`[data-lang="${lang}"]`).focus();return;}if(b.hasAttribute('data-random')){random();return;}if(b.hasAttribute('data-feed')){document.getElementById('feed-start').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.getElementById('feed-title').focus({preventScroll:true});return;}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.filter===filter)));document.getElementById('feed').innerHTML=feed();return;}if(b.dataset.open){openItem(b.dataset.open);return;}if(b.dataset.save){const id=b.dataset.save,remove=state.saved.includes(id);state.saved=remove?state.saved.filter(x=>x!==id):[...state.saved,id];persist();document.querySelectorAll(`[data-save="${id}"]`).forEach(el=>{el.setAttribute('aria-pressed',String(!remove));el.setAttribute('aria-label',saveLabel(id));if(el.querySelector('span'))el.querySelector('span').textContent=saveLabel(id);});const count=document.querySelector('.count');if(count){count.textContent=state.saved.length;count.parentElement.setAttribute('aria-label',L('Minha mochila','My backpack')+': '+state.saved.length);}if(location.hash==='#saved'&&!dialog.open)render();toast(remove?L('Removido da mochila.','Removed from backpack.'):L('Descoberta guardada na mochila.','Discovery saved to your backpack.'));return;}if(b.dataset.interest){const cat=b.dataset.interest;state.interests=state.interests.includes(cat)?state.interests.filter(x=>x!==cat):[...state.interests,cat];persist();b.setAttribute('aria-pressed',String(state.interests.includes(cat)));return;}if(b.hasAttribute('data-answer')){answer=Number(b.dataset.answer);render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest'});document.querySelector('[data-next],[data-retry]')?.focus({preventScroll:true});return;}if(b.hasAttribute('data-retry')){answer=null;render();document.querySelector('.answer').focus();return;}if(b.hasAttribute('data-next')){if(qIndex===2){state.quizDone=true;persist();result=true;}else qIndex++;answer=null;render();document.querySelector('h1').setAttribute('tabindex','-1');document.querySelector('h1').focus();return;}if(b.hasAttribute('data-replay')){qIndex=0;answer=null;result=false;render();return;}if(b.hasAttribute('data-reset')){state=fresh();persist();qIndex=0;answer=null;result=false;render();toast(L('Dados locais do playtest limpos.','Local playtest data cleared.'));}});
document.getElementById('close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');current=null;if(location.hash==='#saved')render();});window.addEventListener('hashchange',()=>{if(dialog.open)dialog.close();render(true);});render();
